css:
/* Corporate / Executive theme — navy + gold accents, data-dense layout */
.valuation-sim-container {
    padding: 28px 24px;
    background: #f4f6fa;
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
    color: #1a2744;
}

.valuation-sim-header {
    display: flex;
    align-items: stretch;
    background: #1a2744;
    border-radius: 4px;
    overflow: hidden;
    margin-bottom: 24px;
    box-shadow: 0 4px 16px rgba(26,39,68,0.18);
}
.valuation-sim-header-stripe {
    width: 8px;
    background: linear-gradient(180deg, #c9a961 0%, #a88845 100%);
}
.valuation-sim-header-content {
    padding: 22px 28px;
    color: #ffffff;
}
.valuation-sim-header h1 {
    font-size: 1.55rem;
    font-weight: 600;
    margin: 0 0 4px 0;
    letter-spacing: 0.01em;
    color: #ffffff;
}
.valuation-sim-subtitle {
    font-size: 0.88rem;
    color: #c9a961;
    letter-spacing: 0.03em;
}

.valuation-sim-period-counter {
    display: inline-block;
    padding: 8px 16px;
    background: #ffffff;
    border: 1px solid #d1d8e0;
    border-left: 4px solid #c9a961;
    border-radius: 3px;
    font-size: 0.85rem;
    color: #435270;
    margin-bottom: 20px;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    font-weight: 600;
}
.valuation-sim-period-counter span {
    margin: 0 4px;
}
.valuation-sim-period-counter #currentDay,
.valuation-sim-period-counter #maxPeriods {
    color: #1a2744;
    font-weight: 700;
}

.valuation-sim-status-cards {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: 16px;
    margin-bottom: 24px;
}
.valuation-sim-status-card {
    background: #ffffff;
    border: 1px solid #d1d8e0;
    border-top: 3px solid #1a2744;
    padding: 18px 20px;
    border-radius: 3px;
    transition: box-shadow 0.2s ease;
}
.valuation-sim-status-card:hover {
    box-shadow: 0 4px 12px rgba(26,39,68,0.1);
}
.valuation-sim-status-card:nth-child(2) {
    border-top-color: #c9a961;
}
.valuation-sim-status-card:nth-child(3) {
    border-top-color: #2f7a4a;
}
.valuation-sim-status-card:nth-child(4) {
    border-top-color: #7a3e2f;
}
.valuation-sim-label {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: #8593a8;
    margin-bottom: 6px;
    font-weight: 600;
}
.valuation-sim-value {
    font-size: 1.75rem;
    font-weight: 700;
    color: #1a2744;
    line-height: 1.1;
}

.valuation-sim-briefing {
    display: flex;
    gap: 16px;
    background: #ffffff;
    border: 1px solid #d1d8e0;
    border-radius: 3px;
    padding: 18px 22px;
    margin-bottom: 20px;
}
.valuation-sim-briefing-badge {
    flex: 0 0 auto;
    width: 48px;
    height: 48px;
    background: #1a2744;
    color: #c9a961;
    border-radius: 3px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: 700;
    font-size: 1.05rem;
    letter-spacing: 0.05em;
}
.valuation-sim-briefing-body {
    flex: 1;
}
.valuation-sim-briefing h3 {
    font-size: 1.1rem;
    font-weight: 600;
    color: #1a2744;
    margin: 0 0 6px 0;
}
.valuation-sim-brief-text {
    font-size: 0.92rem;
    color: #435270;
    line-height: 1.55;
}

.valuation-sim-controls {
    background: #ffffff;
    border: 1px solid #d1d8e0;
    border-radius: 3px;
    padding: 24px 28px;
    margin-bottom: 24px;
}
.valuation-sim-panel h3 {
    font-size: 1.05rem;
    font-weight: 600;
    color: #1a2744;
    margin: 0 0 16px 0;
    padding-bottom: 10px;
    border-bottom: 2px solid #c9a961;
    display: inline-block;
}

.valuation-sim-reference {
    background: #f8f9fc;
    border: 1px solid #e5e9f0;
    border-radius: 3px;
    padding: 12px 16px;
    margin-bottom: 18px;
    font-size: 0.85rem;
}
.valuation-sim-ref-row {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 5px 0;
    color: #435270;
    border-bottom: 1px dotted #e5e9f0;
}
.valuation-sim-ref-row:last-child {
    border-bottom: none;
}
.valuation-sim-ref-row span:last-child {
    font-weight: 600;
    color: #1a2744;
    font-variant-numeric: tabular-nums;
}

.valuation-sim-form-row {
    display: flex;
    flex-direction: column;
    gap: 6px;
    margin-bottom: 14px;
    max-width: 520px;
}
.valuation-sim-form-row label {
    font-size: 0.82rem;
    font-weight: 600;
    color: #435270;
    text-transform: uppercase;
    letter-spacing: 0.05em;
}
.valuation-sim-controls input[type="number"],
.valuation-sim-controls input[type="text"],
.valuation-sim-controls select {
    background: #ffffff;
    border: 1px solid #c1cad8;
    color: #1a2744;
    border-radius: 3px;
    padding: 9px 12px;
    font-size: 0.95rem;
    width: 100%;
    transition: border-color 0.15s ease, box-shadow 0.15s ease;
    font-family: inherit;
}
.valuation-sim-controls input[type="number"]:focus,
.valuation-sim-controls select:focus {
    border-color: #c9a961;
    outline: none;
    box-shadow: 0 0 0 3px rgba(201,169,97,0.18);
}
.valuation-sim-controls select option {
    background: #ffffff;
    color: #1a2744;
}

.valuation-sim-insight {
    background: linear-gradient(135deg, #fff9ec 0%, #fdf3d8 100%);
    border: 1px solid #c9a961;
    border-left: 4px solid #a88845;
    border-radius: 3px;
    padding: 14px 18px;
    margin-bottom: 20px;
}
.valuation-sim-insight-header {
    font-weight: 700;
    color: #6e5422;
    margin-bottom: 6px;
    font-size: 0.92rem;
    letter-spacing: 0.03em;
}
.valuation-sim-insight-body {
    font-size: 0.88rem;
    color: #5c4a20;
    line-height: 1.55;
}

.valuation-sim-buttons {
    display: flex;
    gap: 10px;
    margin-top: 20px;
    padding-top: 18px;
    border-top: 1px solid #e5e9f0;
}
.valuation-sim-container .btn {
    border-radius: 3px;
    padding: 10px 22px;
    font-weight: 600;
    letter-spacing: 0.04em;
    font-size: 0.9rem;
    transition: all 0.15s ease;
}
.valuation-sim-container .btn-primary {
    background: #1a2744;
    border-color: #1a2744;
    color: #ffffff;
}
.valuation-sim-container .btn-primary:hover {
    background: #0f182b;
    border-color: #0f182b;
    box-shadow: 0 4px 12px rgba(26,39,68,0.25);
}
.valuation-sim-container .btn-outline-secondary {
    background: transparent;
    border-color: #c1cad8;
    color: #435270;
}
.valuation-sim-container .btn-outline-secondary:hover {
    background: #f4f6fa;
    border-color: #8593a8;
    color: #1a2744;
}

.valuation-sim-history {
    background: #ffffff;
    border: 1px solid #d1d8e0;
    border-radius: 3px;
    padding: 20px 24px;
    margin-bottom: 24px;
}
.valuation-sim-history h3,
.valuation-sim-chart h3 {
    font-size: 1rem;
    font-weight: 600;
    color: #1a2744;
    margin: 0 0 14px 0;
    text-transform: uppercase;
    letter-spacing: 0.06em;
}
.valuation-sim-history .table {
    font-size: 0.88rem;
    margin: 0;
    color: #1a2744;
}
.valuation-sim-history .table thead th {
    background: #1a2744;
    color: #c9a961;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    font-size: 0.72rem;
    border: none;
    padding: 10px 12px;
}
.valuation-sim-history .table tbody td {
    padding: 10px 12px;
    border-top: 1px solid #e5e9f0;
    font-variant-numeric: tabular-nums;
}
.valuation-sim-history .table-striped tbody tr:nth-of-type(odd) {
    background: #f8f9fc;
}

.valuation-sim-chart {
    background: #ffffff;
    border: 1px solid #d1d8e0;
    border-radius: 3px;
    padding: 20px 24px;
    height: 360px;
}
.valuation-sim-chart canvas {
    max-height: 280px;
}

@media (max-width: 768px) {
    .valuation-sim-container {
        padding: 16px 12px;
    }
    .valuation-sim-header {
        flex-direction: column;
    }
    .valuation-sim-header-stripe {
        width: 100%;
        height: 6px;
    }
    .valuation-sim-header h1 {
        font-size: 1.2rem;
    }
    .valuation-sim-status-cards {
        grid-template-columns: repeat(2, 1fr);
    }
    .valuation-sim-value {
        font-size: 1.35rem;
    }
    .valuation-sim-controls {
        padding: 18px 16px;
    }
    .valuation-sim-briefing {
        flex-direction: column;
    }
}

