                ds.hbuChoice = d.hbuChoice;
                ds.hbuValue = d.hbuValue;
                var correctHbu = (d.hbuChoice === '1');
                var valuePct = Math.abs(d.hbuValue - this.TARGETS.hbuValue) / this.TARGETS.hbuValue;
                var accuracy = Math.max(0, 40 - valuePct * 160);
                if (correctHbu) {
                    roundScore = 60 + accuracy;
                    commentary = window.mySimulation.t('feedback_hbu_correct');
                } else {
                    roundScore = 20 + accuracy * 0.5;
                    commentary = window.mySimulation.t('feedback_hbu_wrong');
                }
                periodResult.hbuChoice = d.hbuChoice;
                periodResult.hbuValue = d.hbuValue;
            } else if (period === 2) {
                ds.compValue = d.compValue;
                ds.incomeValue = d.incomeValue;
                ds.residualValue = d.residualValue;
                var s1 = Math.max(0, 34 - Math.abs(d.compValue - this.TARGETS.comp) / this.TARGETS.comp * 120);
                var s2 = Math.max(0, 34 - Math.abs(d.incomeValue - this.TARGETS.income) / this.TARGETS.income * 120);
                var s3 = Math.max(0, 34 - Math.abs(d.residualValue - this.TARGETS.residual) / this.TARGETS.residual * 120);
                roundScore = s1 + s2 + s3;
                commentary = window.mySimulation.t('feedback_val');
                periodResult.compValue = d.compValue;
                periodResult.incomeValue = d.incomeValue;
                periodResult.residualValue = d.residualValue;
            } else if (period === 3) {
                ds.researched = (d.research === 'yes');
                if (ds.researched) {
                    ds.rezoningKnown = true;
                    ds.researchCost = 0.05;
                    ds.cash -= 0.05;
                    roundScore = 80;
                    commentary = window.mySimulation.t('feedback_research_yes');
                } else {
                    roundScore = 20;
                    commentary = window.mySimulation.t('feedback_research_no');
                }
                periodResult.research = d.research;
                periodResult.rezoning = ds.rezoningKnown ? 'Yes' : 'No';
            } else if (period === 4) {
                ds.negChoice = d.negChoice;
                ds.counterPrice = d.counterPrice;
                var dealValue = 0;
                var known = ds.rezoningKnown;

                if (d.negChoice === 'A') {
                    dealValue = 5.8;
                    commentary = window.mySimulation.t('feedback_neg_A');
                    roundScore = 35;
                } else if (d.negChoice === 'B') {
                    if (known) {
                        dealValue = 0.7 * 9.0 + 0.3 * 5.5;
                        commentary = window.mySimulation.t('feedback_neg_B_known');
                        roundScore = 70;
                    } else {
                        dealValue = 0.5 * 7.8 + 0.5 * 5.2;
                        commentary = window.mySimulation.t('feedback_neg_B_unknown');
                        roundScore = 40;
                    }
                } else if (d.negChoice === 'C') {
                    var price = d.counterPrice;
                    if (known && price >= 7.0 && price <= 8.0) {
                        dealValue = price + 0.35;
                        commentary = window.mySimulation.t('feedback_neg_C_optimal');
                        roundScore = 100;
                    } else if (known && price < 7.0) {
                        dealValue = price;
                        commentary = window.mySimulation.t('feedback_neg_C_low');
                        roundScore = 60;
                    } else if (known && price > 8.0) {
                        dealValue = 5.8;
                        commentary = window.mySimulation.t('feedback_neg_C_high');
                        roundScore = 30;
                    } else {
                        dealValue = Math.min(price, 6.2);
                        commentary = window.mySimulation.t('feedback_neg_C_noresearch');
                        roundScore = 55;
                    }
                } else if (d.negChoice === 'D') {
                    if (known) {
                        dealValue = 8.2;
                        commentary = window.mySimulation.t('feedback_neg_D_known');
                        roundScore = 85;
                    } else {
                        dealValue = 6.2;
                        commentary = window.mySimulation.t('feedback_neg_D_unknown');
                        roundScore = 50;
                    }
                } else if (d.negChoice === 'E') {
                    dealValue = 5.5;
                    commentary = window.mySimulation.t('feedback_neg_E');
                    roundScore = 40;
                }
                ds.dealValue = dealValue;
                ds.cash += dealValue;
                periodResult.strategy = d.negChoice;
                periodResult.counterPrice = d.counterPrice;
                periodResult.dealValue = dealValue;
            }

            ds.totalScore += roundScore;
            // Platform score: running totalScore, the score getPerformanceSummary reports, over its maximum of 382 (100 + 102 + 80 + 100), scaled to 0-100
            state.domainState.performance = Object.assign({}, state.domainState.performance || {}, { overallScore: Math.max(0, Math.min(100, Math.round(100 * ds.totalScore / 382))) });
            ds.scoreHistory.push(Math.round(roundScore));
            ds.cashHistory.push(Number(ds.cash.toFixed(2)));

            periodResult.score = Math.round(roundScore);
            periodResult.totalScore = Math.round(ds.totalScore);
            periodResult.cash = Number(ds.cash.toFixed(2));
            periodResult.commentary = commentary;

            var self = this;
            setTimeout(((__eqilNext) => function() {
                self._updateBriefing({ currentPeriod: __eqilNext });
            })(state.currentPeriod + 1), 500);

            return periodResult;
        }

        _t(key) {
            try { return window.mySimulation.t(key); }
            catch (e) {
                var tr = this.getTranslations();
                return (tr.es || {})[key] || key;
            }
        }

        _updateBriefing(state) {
            var period = state.currentPeriod || 1;
            if (period > 4) period = 4;
            var t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : function(k){ return k; };

            var badgeEl = document.getElementById('roundBadge');
            if (badgeEl) badgeEl.textContent = 'R' + period;

            var titleEl = document.getElementById('roundTitle');
            var briefEl = document.getElementById('briefingText');
            var titles = ['round1_title', 'round2_title', 'round3_title', 'round4_title'];
            var briefs = ['round1_brief', 'round2_brief', 'round3_brief', 'round4_brief'];
            if (titleEl) titleEl.textContent = t(titles[period - 1]);
            if (briefEl) briefEl.innerHTML = t(briefs[period - 1]);

            var panels = ['panelHbu', 'panelValuation', 'panelResearch', 'panelNegotiation'];
            panels.forEach(function(id) {
                var el = document.getElementById(id);
                if (el) el.style.display = 'none';
            });
            var activePanel = document.getElementById(panels[period - 1]);
            if (activePanel) activePanel.style.display = 'block';

            var rezoningPanel = document.getElementById('rezoningInfo');
            if (rezoningPanel) {
                var s = window.mySimulation ? window.mySimulation.state : null;
                var known = s && s.domainState && s.domainState.rezoningKnown;
                rezoningPanel.style.display = known ? 'block' : 'none';
            }
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('scoreDisplay', 'domainState.totalScore', function(v) {
                return Math.round(v || 0).toString();
            });
            uiManager.bind('cashDisplay', 'domainState.cash', function(v) {
                var n = Number(v || 0);
                var sign = n < 0 ? '-' : '';
                return sign + '$' + Math.abs(n).toFixed(2) + 'M';
            });
        }

