        getHint(state, results) {
            if (!results) return null;
            var period = results.period || state.currentPeriod;
            if (period === 1 && results.hbuChoice && results.hbuChoice !== '1') {
                return window.mySimulation.t('hint_hbu');
            }
            if (period === 2) {
                var ds = state.domainState;
                var off1 = Math.abs((ds.compValue || 0) - this.TARGETS.comp) / this.TARGETS.comp;
                var off2 = Math.abs((ds.incomeValue || 0) - this.TARGETS.income) / this.TARGETS.income;
                var off3 = Math.abs((ds.residualValue || 0) - this.TARGETS.residual) / this.TARGETS.residual;
                if (off1 > 0.15 || off2 > 0.15 || off3 > 0.3) return window.mySimulation.t('hint_val');
            }
            if (period === 3 && results.research === 'no') {
                return window.mySimulation.t('hint_research');
            }
            if (period === 4 && results.strategy === 'A') {
                return window.mySimulation.t('hint_negA');
            }
            return null;
        }

