            return [
                { key: 'results.period', label: 'Round', i18nKey: 'col_round' },
                { key: 'results.score', label: 'Score', i18nKey: 'col_score' },
                { key: 'results.totalScore', label: 'Total', i18nKey: 'col_total' },
                { key: 'results.commentary', label: 'Commentary', i18nKey: 'col_commentary' },
                { key: 'results.cash', label: 'Cash ($M)', i18nKey: 'col_cash', formatter: function(v) {
                    if (v === undefined || v === null) return '';
                    return '$' + Number(v).toFixed(2) + 'M';
                } }
            ];
        }

        getPresets() { return null; }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var ds = (window.mySimulation && window.mySimulation.state) ? window.mySimulation.state.domainState : {};
            var total = ds.totalScore || 0;
            var cash = ds.cash || 0;
            var performance = 'Principiante';
            if (total >= 320 && cash >= 7.5) performance = 'Excelente';
            else if (total >= 240 && cash >= 6.5) performance = 'Bueno';
            else if (total >= 160) performance = 'Aceptable';

            var insights = [];
            if (cash >= 7.5) insights.push(window.mySimulation.t('summary_insight_high'));
            else if (cash >= 6.0) insights.push(window.mySimulation.t('summary_insight_mid'));
            else insights.push(window.mySimulation.t('summary_insight_low'));
            if (ds.researched) insights.push(window.mySimulation.t('summary_research_yes'));
            else insights.push(window.mySimulation.t('summary_research_no'));

            var perfKeys = { 'Principiante': 'perf_beginner', 'Aceptable': 'perf_acceptable', 'Bueno': 'perf_good', 'Excelente': 'perf_excellent' };
            var performanceLabel = (window.mySimulation && perfKeys[performance]) ? window.mySimulation.t(perfKeys[performance]) : performance;

            return {
                totalScore: Math.round(total),
                netPosition: Number(cash.toFixed(2)),
                dealValue: ds.dealValue || 0,
                // Shown on the end screen: the band label in the player language (the Spanish literal above is only the lookup id)
                performance: performanceLabel,
                performanceLabel: performanceLabel,
                insights: insights
            };
        }

